    """Qué porcentaje representa `parte` sobre `total`."""
    if total == 0:
        raise ZeroDivisionError("El total no puede ser cero.")
    return (parte / total) * 100


def es_palindromo(numero: int) -> bool:
    """Devuelve True si la representación decimal de `numero` es un palíndromo.

    Los números negativos se evalúan ignorando el signo.
    """
    s = str(abs(numero))
    return s == s[::-1]

